 View find(View v,String s){if(s.equals(v.getTag())||s.contentEquals(v.getContentDescription()==null?"":v.getContentDescription())||v instanceof TextView&&s.contentEquals(((TextView)v).getText()))return v;if(v instanceof ViewGroup)for(int i=0;i<((ViewGroup)v).getChildCount();i++){View result=find(((ViewGroup)v).getChildAt(i),s);if(result!=null)return result;}return null;}
 void click(View v){check(v!=null,"Missing button");View item=v;while(!item.isClickable()&&item.getParent() instanceof View)item=(View)item.getParent();final View target=item;runOnMainSync(()->target.performClick());}
