 public void onStart(){Bundle out=new Bundle();Activity active=null;try{ClassLoader cl=getTargetContext().getClassLoader();api=cl.loadClass("app.kinnect.live.NativeApi").getField("shared").get(null);try(InputStream in=getContext().getAssets().open("store33-fixture.json")){ByteArrayOutputStream bytes=new ByteArrayOutputStream();byte[] b=new byte[4096];int n;while((n=in.read(b))!=-1)bytes.write(b,0,n);fixture=new JSONObject(bytes.toString("UTF-8"));}theme=getTargetContext().getSharedPreferences("kinnect_settings",0).getString("theme","auto");Class<?> design=cl.loadClass("app.kinnect.live.StorePackageDesign"),artType=cl.loadClass("app.kinnect.live.StorePackageDesign$Art");Method identity=design.getDeclaredMethod("identity",String.class);identity.setAccessible(true);Constructor<?> ctor=artType.getDeclaredConstructor(Activity.class,JSONObject.class);ctor.setAccessible(true);JSONArray plans=fixture.getJSONObject("store").getJSONArray("packages");Class<?> icons=cl.loadClass("app.kinnect.live.WebIcons");Method resolve=icons.getDeclaredMethod("resolve",Context.class,String.class);resolve.setAccessible(true);check((Integer)resolve.invoke(null,getTargetContext(),"crown")!=0,"Crown vector missing");check((Integer)resolve.invoke(null,getTargetContext(),"star")!=0,"Star vector missing");Set<String> meanings=new HashSet<>(),images=new HashSet<>();Bitmap gallery=Bitmap.createBitmap(960,900,Bitmap.Config.ARGB_8888);Canvas grid=new Canvas(gallery);
 for(String variant:new String[]{"light","dark"}){getTargetContext().getSharedPreferences("kinnect_settings",0).edit().putString("theme",variant).commit();active=open("StoreActivity");final Activity store=active;runOnMainSync(()->{try{set(store,"catalog",fixture.getJSONObject("store"));call(store,"draw",new Class[]{});}catch(Exception e){throw new RuntimeException(e);}});Thread.sleep(200);for(String tab:new String[]{"style","studio","live","gifts","member","owned"}){runOnMainSync(()->{try{call(store,"selectTab",new Class[]{String.class},tab);}catch(Exception e){throw new RuntimeException(e);}});Thread.sleep(100);bounds(store.getWindow().getDecorView());if(tab.equals("studio"))check(find(store.getWindow().getDecorView(),"Đang miễn phí trải nghiệm")==null,"Free banner returned");if(variant.equals("light")&&!tab.equals("owned"))shot(store,"store33-"+tab+".png");}
 for(int i=0;i<plans.length();i++){JSONObject plan=plans.getJSONObject(i);String[] copy=(String[])identity.invoke(null,plan.getString("id"));check(copy.length==6,"Missing package meaning/benefits");if(variant.equals("light")){check(meanings.add(copy[1]),"Duplicated meaning");Bitmap bitmap=Bitmap.createBitmap(320,180,Bitmap.Config.ARGB_8888);Canvas canvas=new Canvas(bitmap);final int index=i;runOnMainSync(()->{try{View art=(View)ctor.newInstance(store,plan);art.layout(0,0,320,180);art.draw(canvas);}catch(Exception e){throw new RuntimeException(e);}});ByteArrayOutputStream encoded=new ByteArrayOutputStream();bitmap.compress(Bitmap.CompressFormat.PNG,100,encoded);String digest=java.util.Arrays.toString(java.security.MessageDigest.getInstance("SHA-256").digest(encoded.toByteArray()));check(images.add(digest),"Artwork reused: "+plan.getString("id"));grid.drawBitmap(bitmap,(index%3)*320,(index/3)*180,null);bitmap.recycle();}
 runOnMainSync(()->{try{call(store,"showPlan",new Class[]{JSONObject.class},plan);}catch(Exception e){throw new RuntimeException(e);}});Thread.sleep(120);android.view.accessibility.AccessibilityNodeInfo window=getUiAutomation().getRootInActiveWindow();check(window!=null&&!window.findAccessibilityNodeInfosByText(copy[1]).isEmpty(),"Missing detail meaning");if(!plan.optBoolean("available"))check(window.findAccessibilityNodeInfosByText("Kích hoạt").isEmpty(),"Unavailable design charged");if(variant.equals("light")&&(i==0||i==3||i==9||i==11||i==13))shot(store,"store33-detail-"+plan.getString("id")+".png");getUiAutomation().executeShellCommand("input keyevent 4").close();Thread.sleep(100);}
 Class<?> effects=cl.loadClass("app.kinnect.live.SuccessEffects");Method message=effects.getDeclaredMethod("message",Activity.class,String.class),clear=effects.getDeclaredMethod("clear",Activity.class),purchase=effects.getDeclaredMethod("purchase",Activity.class,JSONObject.class,Runnable.class);message.setAccessible(true);clear.setAccessible(true);purchase.setAccessible(true);java.util.concurrent.atomic.AtomicBoolean used=new java.util.concurrent.atomic.AtomicBoolean();runOnMainSync(()->{try{check(!(Boolean)message.invoke(null,store,"Lỗi máy chủ"),"Error converted to success");check((Boolean)message.invoke(null,store,"Đã áp dụng phong cách."),"Success feedback missing");}catch(Exception e){throw new RuntimeException(e);}});Thread.sleep(250);check(find(store.getWindow().getDecorView(),"feedback:success")!=null,"Visual confirmation absent");runOnMainSync(()->{try{clear.invoke(null,store);purchase.invoke(null,store,plans.optJSONObject(0),(Runnable)()->used.set(true));}catch(Exception e){throw new RuntimeException(e);}});Thread.sleep(500);View effect=find(store.getWindow().getDecorView(),"feedback:purchase");check(effect!=null,"Purchase animation missing");if(variant.equals("light")){runOnMainSync(()->{try{Object spark=((ViewGroup)effect).getChildAt(1);android.animation.ValueAnimator anim=(android.animation.ValueAnimator)get(spark,"anim");if(anim!=null){anim.setCurrentPlayTime(650);anim.pause();}}catch(Exception e){throw new RuntimeException(e);}});shot(store,"store33-purchase-success.png");}click(find(store.getWindow().getDecorView(),"Dùng ngay"));check(used.get(),"Use action absent");check(find(store.getWindow().getDecorView(),"feedback:purchase")==null,"Purchase overlay leaked");runOnMainSync(()->store.finish());
 active=open("CoinGrantActivity");final Activity grants=active;runOnMainSync(()->{try{call(grants,"renderPeople",new Class[]{JSONArray.class},fixture.getJSONArray("people"));}catch(Exception e){throw new RuntimeException(e);}});Thread.sleep(150);bounds(grants.getWindow().getDecorView());android.widget.EditText amount=(android.widget.EditText)find(grants.getWindow().getDecorView(),"grants:amount");int expected=variant.equals("dark")?0xfff1eff7:0xff1f1d2b;check(amount.getCurrentTextColor()==expected,"Admin amount color washed out");android.widget.EditText search=(android.widget.EditText)find(grants.getWindow().getDecorView(),"grants:search");check(search.getCurrentTextColor()==expected,"Admin search text color");check(search.getCurrentHintTextColor()!=android.graphics.Color.WHITE,"White hint on light background");shot(grants,"store33-admin-"+variant+".png");click(find(grants.getWindow().getDecorView(),"grants:all"));check(!search.isEnabled(),"All-member disabled state missing");Thread.sleep(200);bounds(grants.getWindow().getDecorView());runOnMainSync(()->grants.finish());}

 try(FileOutputStream file=new FileOutputStream(new File(getTargetContext().getExternalFilesDir(null),"store33-art-gallery.png"))){gallery.compress(Bitmap.CompressFormat.PNG,100,file);}gallery.recycle();out.putString("result","PASS "+checks+":15 unique artwork/meaning identities,30 detail sheets light+dark,6tabs price/no-free-state,success/error separation,purchase effect/use action cleanup,admin light/dark contrast;320dp/font130;no public mutations");finish(Activity.RESULT_OK,out);
 }catch(Throwable e){out.putString("error",e.toString());finish(Activity.RESULT_CANCELED,out);}finally{final Activity last=active;runOnMainSync(()->{if(last!=null)last.finish();});getTargetContext().getSharedPreferences("kinnect_settings",0).edit().putString("theme",theme==null?"auto":theme).commit();}}
